// NowPlaying.js

import React, { useState, useRef, useEffect } from 'react';
import './NowPlaying.css';
import playIconBlack from '../../assets/playIconBlack.png';
import pauseIcon from '../../assets/pauseIcon.png';

function NowPlaying({ name, linkSrc }) {
    const audioRef = useRef(null);
    const [isPlaying, setIsPlaying] = useState(false);
    const [currentTime, setCurrentTime] = useState(0);
    const [duration, setDuration] = useState(0);

    const togglePlayPause = () => {
        const audio = audioRef.current;
        if (!audio.paused) {
            audio.pause();
            setIsPlaying(false);
        } else if (audio.paused) {
            audio.play();
            setIsPlaying(true);
        }
    };

    const handleTimeUpdate = () => {
        const audio = audioRef.current;
        setCurrentTime(audio.currentTime);
    };

    const handleSeek = (e) => {
        const audio = audioRef.current;
        const newTime = (e.target.value / 100) * duration;
        audio.currentTime = newTime;
        setCurrentTime(newTime);
    };

    useEffect(() => {
        const audio = audioRef.current;
        audio.addEventListener('loadedmetadata', () => {
            setDuration(audio.duration);
        });

        audio.addEventListener('timeupdate', handleTimeUpdate);

        return () => {
            audio.removeEventListener('loadedmetadata', () => {
                setDuration(audio.duration);
            });

            audio.removeEventListener('timeupdate', handleTimeUpdate);
        };
    }, []);

    const formatTime = (seconds) => {
        const minutes = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${minutes}:${secs < 10 ? '0' : ''}${secs}`;
    };

    return (
        <div className='nowPlaying'>
            <p className='currTitle'>{/* Now Playing:  */}{name}</p>

            <div className='audioPlayer'>
                <button className='playPause' onClick={togglePlayPause}>
                    {/* {isPlaying ? 'Pause' : 'Play'} */}
                    <img src={isPlaying ? pauseIcon : playIconBlack} alt={isPlaying ? 'Play' : 'Pause'} className='controlIcon'/>
                </button>
                <input
                    type='range'
                    className='seekBar'
                    value={(currentTime / duration) * 100 || 0}
                    onChange={handleSeek}
                />
                <span className='time'>{formatTime(currentTime)}</span>
                <audio ref={audioRef} src={linkSrc} className='audio' />
            </div>
        </div>

    );
};

export default NowPlaying;